Here’s a quick example in Python using the `requests` library:

```python
import requests

url = "https://api.yourservice.com/files"
headers = {
    "Authorization": "Bearer apikey_456",
    "Accept": "application/json"
}
params = {
    "domain": "example.net",
    "limit": 20
}

response = requests.get(url, headers=headers, params=params)

if response.status_code == 200:
    data = response.json()
    # Assuming the response contains a list of files
    for file in data.get("files", []):
        print(f"ID: {file['id']}")
        # Print any context attributes you need
        for key, value in file.get("context", {}).items():
            print(f"  {key}: {value}")
else:
    print(f"Error {response.status_code}: {response.text}")
```

